css:
/* Стопка карточек: прилипание делает CSS (position: sticky), JS только добавляет глубину через --depth.
   Без JS стопка всё равно работает. Предки секции НЕ должны иметь overflow: hidden/auto — это ломает sticky;
   чтобы убрать горизонтальный скролл страницы, используйте overflow-x: clip. */
.stack {
  --stack-top: 96px;   /* высота липкой шапки сайта + воздух */
  --stack-step: 16px;  /* сколько видно от карточки под следующей */
  --stack-gap: 24px;
  --stack-hold: 12vh;  /* пауза: стопка держится, прежде чем уехать */
  padding-block: 64px;
}
.stack__title { margin: 0 0 32px; }
.stack__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--stack-gap);
}
/* Номер карточки (--i) и число карточек после неё (--rest) считает CSS — инлайновые стили не нужны (до 5 карточек). */
.stack__card:nth-child(2) { --i: 1; }
.stack__card:nth-child(3) { --i: 2; }
.stack__card:nth-child(4) { --i: 3; }
.stack__card:nth-child(5) { --i: 4; }
.stack__card:nth-last-child(2) { --rest: 1; }
.stack__card:nth-last-child(3) { --rest: 2; }
.stack__card:nth-last-child(4) { --rest: 3; }
.stack__card:nth-last-child(5) { --rest: 4; }
.stack__card {
  position: sticky;
  top: calc(var(--stack-top) + var(--i, 0) * var(--stack-step));
  /* Нижний отступ входит в липкую рамку: у всех карточек она кончается на одной линии,
     и стопка уходит целиком — края прошлых карточек не схлопываются под верхнюю. */
  margin-bottom: calc(var(--rest, 0) * var(--stack-step));
}
/* В потоке этот отступ гасит следующая карточка: расстояние между карточками остаётся --stack-gap. */
.stack__card + .stack__card { margin-top: calc(-1 * (var(--rest, 0) + 1) * var(--stack-step)); }
/* Пауза после последней карточки — отдельным элементом списка: отступ самой карточки входит в её
   липкую рамку и паузы не даёт (последняя карточка сразу наезжала бы на полоски остальных). */
.stack__list::after { content: ""; flex: 0 0 var(--stack-hold); }
/* Фокус внутри закрытой карточки: поднимаем её над стопкой (WCAG 2.4.11) */
.stack__card:focus-within { z-index: 1; }
.stack__inner {
  position: relative;
  box-sizing: border-box;
  min-height: min(26rem, 60vh);
  min-height: min(26rem, 60svh);
  padding: clamp(24px, 4vw, 48px);
  border-radius: 24px;
  background: var(--surface, #ffffff);
  color: var(--text, #14161a);
  border: 1px solid var(--border, #d9dce3);
  box-shadow: 0 1px 2px rgba(20, 22, 26, .06), 0 16px 40px -16px rgba(20, 22, 26, .22);
  transform-origin: 50% 0; /* верхний край на месте: полоска над следующей карточкой не прячется */
  transform: scale(calc(1 - var(--depth, 0) * .04));
  will-change: transform;
  transition: border-color 200ms cubic-bezier(.2, 0, 0, 1);
}
.stack__inner::after { /* затемнение глубины: дешевле, чем filter */
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: #000000;
  opacity: calc(var(--depth, 0) * .1);
  pointer-events: none;
}
.stack__card:focus-within .stack__inner {
  transform: none;
  border-color: var(--primary, #2446d8);
}
.stack__card:focus-within .stack__inner::after { opacity: 0; }
.stack__num { display: block; font-size: 14px; font-weight: 600; letter-spacing: .08em; opacity: .7; }
.stack__inner h3 { margin: 12px 0 8px; font-size: clamp(24px, 3vw, 36px); line-height: 1.15; }
.stack__inner p { margin: 0; max-width: 40ch; font-size: 18px; line-height: 1.6; }
@media (max-width: 640px) {
  .stack { --stack-top: 72px; --stack-step: 10px; --stack-gap: 16px; }
  .stack__inner { min-height: min(22rem, 56vh); min-height: min(22rem, 56svh); }
  .stack__inner p { font-size: 16px; }
}
/* Уровень 1 (iart): стопка и глубина — вестибулярный триггер, убираем. Обычный список, цвет фокуса остаётся.
   Низкий экран (телефон лёжа): карточка выше экрана спрятала бы свой низ под следующую — тоже обычный список. */
@media (prefers-reduced-motion: reduce), (max-height: 560px) {
  .stack__card { position: static; }
  .stack__list::after { display: none; }
  .stack__inner { transform: none; will-change: auto; min-height: 0; }
  .stack__inner::after { opacity: 0; }
}

