// Глубина стопки: чем больше карточек наехало сверху, тем меньше и темнее карточка (--depth 0..3).
(() => {
  const list = document.querySelector('[data-stack]');
  if (!list || !('IntersectionObserver' in window)) return;
  const cards = Array.from(list.children);
  const off = matchMedia('(prefers-reduced-motion: reduce), (max-height: 560px)');
  const last = cards.map(() => -1);
  let raf = 0, visible = false;
  function update() {
    raf = 0;
    const step = parseFloat(getComputedStyle(list).getPropertyValue('--stack-step')) || 0;
    const r = cards.map((c) => c.getBoundingClientRect()); // сначала все чтения
    let depth = 0;
    for (let i = cards.length - 1; i >= 0; i--) {             // потом все записи
      const v = Math.min(depth, 3);
      if (Math.abs(v - last[i]) > 0.002) { last[i] = v; cards[i].style.setProperty('--depth', v.toFixed(3)); }
      if (i > 0) depth += Math.min(1, Math.max(0, (r[i - 1].bottom - r[i].top) / Math.max(1, r[i - 1].height - step)));
    }
  }
  const onScroll = () => { if (!raf) raf = requestAnimationFrame(update); };
  function sync() {
    removeEventListener('scroll', onScroll);
    removeEventListener('resize', onScroll);
    if (off.matches) {
      cancelAnimationFrame(raf); raf = 0;
      cards.forEach((c, i) => { c.style.removeProperty('--depth'); last[i] = -1; });
    } else if (visible) {
      addEventListener('scroll', onScroll, { passive: true });
      addEventListener('resize', onScroll);
      onScroll();
    }
  }
  new IntersectionObserver((es) => { visible = es[es.length - 1].isIntersecting; sync(); }).observe(list);
  off.addEventListener('change', sync);
})();
